    if cat:
        top = max(cat['rows'], key=lambda r: r['amount'])
        out.append({'title': '品类结构：' + top['category'] + '主导', 'detail': top['category'] + '采购金额' + str(round(top['amount'], 2)) + '，占比' + str(round(top['amount_share'] * 100, 1)) + '%，下一周期应保持其主推地位并补齐其余品类。', 'evidence': {'amount': round(top['amount'], 2), 'share_pct': round(top['amount_share'] * 100, 1)}})
    return out

def analyze(datasets):
    def pick(cols):
        return next((d for d in datasets if all(c in d.get('columns', []) for c in cols)), None)
    out = []
    stock = pick(['sku', 'product_name', 'stock_on_hand'])
    sold = pick(['sku', 'product_name_en', 'units_sold'])
    if stock and sold:
        s = {r['sku']: r for r in stock['rows']}
        for r in sold['rows']:
            if r['sku'] in s:
                soh = float(s[r['sku']]['stock_on_hand'])
                us = float(r['units_sold'])
                days = soh / (us / 30.0) if us > 0 else None
                name = r['product_name_en']
                if days is not None and days < 15:
                    out.append({'title': '库存告急：' + name + '（' + r['sku'] + '）', 'detail': '9月销量 ' + str(int(us)) + ' 件，期末库存仅 ' + str(int(soh)) + ' 件，按当月日均销量仅可支撑约 ' + str(round(days, 1)) + ' 天，存在断货风险。', 'evidence': {'sku': r['sku'], 'stock_on_hand': soh, 'units_sold': us, 'days_cover': round(days, 1)}})
                else:
                    out.append({'title': '库存覆盖：' + name + '（' + r['sku'] + '）', 'detail': '9月销量 ' + str(int(us)) + ' 件，期末库存 ' + str(int(soh)) + ' 件，按当月日均销量可支撑约 ' + str(round(days, 1)) + ' 天。', 'evidence': {'sku': r['sku'], 'stock_on_hand': soh, 'units_sold': us, 'days_cover': round(days, 1)}})
    po = pick(['po_number', 'status', 'total_amount', 'eta_date'])
    if po:
        pending = [r for r in po['rows'] if r['status'] != 'completed']
        amt = sum(float(r['total_amount']) for r in pending)
        overdue = [r for r in pending if r['eta_date'] and r['eta_date'] < '2026-09-30']
        out.append({'title': '在途采购单与到货风险', 'detail': '截至9月末仍有 ' + str(len(pending)) + ' 张采购单未完成，合计金额 ' + str(round(amt, 2)) + '；其中 ' + str(len(overdue)) + ' 张预计到货日已早于9月末仍未完成，存在延迟到货风险。', 'evidence': {'pending_count': len(pending), 'pending_amount': round(amt, 2), 'overdue_count': len(overdue)}})
    trend = pick(['month', 'total_amount', 'total_boxes'])
    if trend:
        rows = sorted(trend['rows'], key=lambda r: r['month'])
        months = [r['month'] for r in rows]
        out.append({'title': '采购节奏波动', 'detail': '采购单仅出现在 ' + '、'.join(months) + ' 两个月，8月无采购记录，采购节奏不连续，可能造成供应断档。', 'evidence': {'months': months, 'order_amounts': [round(float(r['total_amount']), 2) for r in rows]}})
    return out
